static const char DEFAULT_SETTINGS_YAML[] = R"PITIMER_DEFAULT(
# Example settings file - copy it to pitimer_settings.yml and edit the copy for your usage
# (the live pitimer_settings.yml is not version controlled, so upgrades never overwrite it).
# See README.md for more documentation/information.
# This file uses the YAML file format described here: https://en.wikipedia.org/wiki/yaml 
# Therefore, any text after the hash/sign/pound symbol '#' is treated as a comment
# and ignored by the parsing code so it used mostly to document the configuration

# config - Main configuration section which controls look and behaviour 
config:
    # enabled - Global ON/OFF switch (True=ON or False=OFF)
    enabled: True
    # header - Subsection for controlling messages displayed at top of screen
    header:
        # font_size - Font size for messages shown at top of screen
        #             Good starting value for 1080p/HD screen is 208, for 1440p/QHD is 256 (use integer multiples of 16 for best results)
        font_size: 208
        # text - Messages at top of screen to display depending on status
        text:
            when_disabled: '**** TIMER DISABLED ****'
            when_idle: 'YOUR CLUB NAME'
            counting_down: 'TIME UNTIL BELL/BUZZER'
            during_buzzer: '--------  LAST END  --------'
        # color - Color of message displayed at top of screen depending on status
        #         Names which can be used listed here: https://www.pygame.org/docs/ref/color_list.html
        color:
            when_disabled: red
            when_idle: white
            counting_down: yellow
            during_buzzer: yellow
    # countdown - Subsection for controlling countdown timer displayed in middle of screen
    countdown:
        # font_size_4_digits - Timer font size when it's below an hour remaining
        #                      Good starting value for 1080p/HD screen is 992, for 1440p/QHD is 1408 (use integer multiples of 16 for best results)
        font_size_4_digits: 992
        # font_size_5_digits - Timer font size When it's an hour or more remaining 
        #                      Good starting value for 1080p/HD screen is 816, for 1440p/QHD is 1088 (use integer multiples of 16 for best results)
        font_size_5_digits: 816
        # color - Color of countdown timer digits displayed depending on moment
        #         Names which can be used listed here: https://www.pygame.org/docs/ref/color_list.html
        color:
            counting_down: green
            during_buzzer: red
    # pace_of_play - Subsection for controlling optional pace of play banner shown between countdown and footer
    pace_of_play:
        # enabled - Display pace of play 'unit_name' banner based on 'unit_duration' seconds (True=ON or False=OFF)
        enabled: True
        # font_size - Font size for pace of play banner shown between countdown and footer
        #             Good starting value for 1080p/HD screen is 224, for 1440p/QHD is 272 (use integer multiples of 16 for best results)
        font_size: 224
        # color - Color of pace of play banner text
        #         Names which can be used listed here: https://www.pygame.org/docs/ref/color_list.html
        color: white
        # unit_name - Text to display of what you are counting for pace (e.g. 'END' for curling, 'HOLE' for golf, etc.)
        unit_name: 'END'
        # unit_duration - Number of integer seconds each unit should take (e.g. 900 for 15 minutes)
        unit_duration: 900
    # footer - Subsection for controlling information displayed at bottom of screen
    footer:
        # font_size - Font size for information shown at bottom of screen
        #             Good starting value for 1080p/HD screen is 96, for 1440p/QHD is 128 (use integer multiples of 16 for best results)
        font_size: 96
        # datetime - Display both date and time in bottom footer (True=ON or False=OFF)
        datetime: True
        # entry_name - Display the name associated with the entry/game in bottom footer (True=ON or False=OFF)
        entry_name: True
    # buzzer - Subsection for controlling any connected bell/buzzer
    buzzer:
        # relays - List of PiRelay V2 Shield relays ('RELAYn' where n can be from 1 to 4)
        #          connected to bell/buzzers/lights (use empty list [] for nothing connected)
        #          e.g. ['RELAY1', 'RELAY2'] or ['RELAY4'] or []
        #          These relays ring when a game's buzzer time is reached.
        relays: ['RELAY1']
        # ring_at_start - Optional: relays to also ring for 'duration' seconds when a
        #                 game STARTS (use empty list [] for no start ring).
        ring_at_start: []
        # countdown - Optional: ring relays a warning 'minutes_before' minutes before
        #             the buzzer time (minutes_before: 0 turns the warning off).
        countdown:
            minutes_before: 0
            relays: []
        # duration - How long to keep relays on (i.e. operating) in integer seconds
        duration: 2
        # header_hold - How long to hold the 'during_buzzer' header message in integer seconds
        header_hold: 299

# schedule - Normal weekly defined schedule
#            All weekdays must be defined and each as a list of entries (i.e. each entry starting with a dash '-')
#            For days without entries (i.e. no bell/buzzers), use an empty list (e.g. Sunday: [])
#            Each entry should be done as an inline block (i.e. a one liner) to help readability
#            Mandatory entry variables are: 
#            - start: start time of game in ISO time HH:MM:SS format (##:##:##) with no leading zeros
#            - buzzer: bell/buzzer time in ISO time HH:MM:SS format (##:##:##) with no leading zeros
#            GOTCHA: Times in the midnight hour (00:00:00 to 00:59:59) must be written be written in seconds since midnight (YAML parser limitation)
#            Optional local entry override variables available are:
#            - name: text string to display in center of footer during countdown and during/after bell/buzzer (default is nothing)
#            - during_buzzer: text string to display in header during and after bell/buzzer (default is config.header.text.during_countdown setting)
#            - header_hold: How long to hold the 'during_buzzer' header message in integer seconds (0 or more, default is config.buzzer.header_hold setting)
#            - pace_of_play: Display pace of play banner (True=ON or False=OFF) (default is config.pace_of_play.enabled setting)
#            - pace_unit_duration: Number of integer seconds each pace of play unit should take (default is config.pace_of_play.unit_duration setting)
schedule:
    Monday:
        - {start: 13:00:00, buzzer: 14:45:00, name: 'DAY LEAGUE'}
        - {start: 19:00:00, buzzer: 20:50:00, name: 'EVENING LEAGUE'}
    Tuesday:
        - {start: 19:00:00, buzzer: 20:05:00, name: 'DOUBLES', pace_unit_duration: 720}
        - {start: 20:20:00, buzzer: 21:25:00, name: 'DOUBLES', pace_unit_duration: 720}
    Wednesday: []
    Thursday:
        - {start: 19:00:00, buzzer: 20:50:00, name: 'EVENING LEAGUE'}
    Friday: []
    Saturday:
        - {start:  9:00:00, buzzer:  9:25:00, name: 'PRACTICE ICE', during_buzzer: '--- PRACTICE ENDING ---', header_hold: 60, pace_of_play: False}
        - {start: 10:00:00, buzzer: 11:50:00, name: 'SATURDAY MIXED'}
    Sunday: []


# exceptions - Specific dates with exceptions to the normal schedule
#              If no exceptions defined yet, use an empty mapping until first date used (i.e. exceptions: {})
#              Dates must be YYYY-MM-DD (ISO style)
#              For dates without entries (i.e. no bell/buzzers wanted), use an empty list (e.g. 2024-12-31: [])
#              Same format and rules for individual entries as a normal daily schedule (see above)
exceptions:
    2026-12-25: [] # No buzzers - club closed
    2027-01-16: # Bonspiel
        - {start:  9:00:00, buzzer: 10:35:00, name: 'BONSPIEL DRAW 1'}
        - {start: 11:00:00, buzzer: 12:35:00, name: 'BONSPIEL DRAW 2'}
)PITIMER_DEFAULT";

